create function private.approval_ready(p uuid,t text,e uuid,n bigint) returns boolean language plpgsql stable set search_path='' as $$ declare pol uuid; rec jsonb; begin execute format('select to_jsonb(x) from public.%I x where id=$1 and project_id=$2',t) into rec using e,p; select id into pol from public.approval_policies where project_id=p and entity_type=t and is_active and coalesce((rule_json->>'minimum_minor')::bigint,0)<=n and (rule_json->>'category_id' is null or rule_json->>'category_id'=rec->>'category_id') order by priority desc limit 1; if pol is null then return true; end if; if rec->>'status'<>'approved' then return false; end if; return exists(select 1 from public.approval_instances where project_id=p and entity_id=e and entity_type=t and policy_id=pol and status='approved' and approved_amount_minor=n and posted_event_id is null and created_at=(select max(created_at) from public.approval_instances where project_id=p and entity_id=e and entity_type=t)); end $$;
create function public.prepare_advance_topup(p_project uuid,p_advance uuid,p_amount text,p_reason text) returns void language plpgsql security definer set search_path='' as $$ begin perform private.assert_finance(p_project); perform 1 from public.projects where id=p_project and status='active' for update; if not found then raise exception 'PROJECT_CLOSED'; end if; if p_amount::bigint<=0 or length(p_reason)<5 then raise exception 'INVALID_TOPUP'; end if; update public.advances set requested_minor=p_amount::bigint,status='draft',purpose=p_reason where id=p_advance and project_id=p_project and status not in ('closed','draft','submitted'); if not found then raise exception 'INVALID_ADVANCE'; end if; perform private.log(p_project,'advance_topup_requested','advances',p_advance,p_reason); end $$;
revoke all on function private.approval_ready(uuid,text,uuid,bigint),public.prepare_advance_topup(uuid,uuid,text,text) from public;
grant execute on function public.prepare_advance_topup(uuid,uuid,text,text) to authenticated;
